// fnsplit(path, drive, dir, name, ext) -> flags (1 wildcards, 2 extension,
// 4 name, 8 directory, 16 drive).  vbn's own: when the path has exactly one
// '\', `dir` gets the path's first character only.  vbn always passes paths
// that start with '\', and then that is the root's "\".
#define __PE_DECL___sub_10008BB1
static int __sub_10008BB1(int path_, void *drive_, void *dir_, void *name_, void *ext_)
{
  const char *path = (const char *)(uintptr_t)path_;
  char *drive = (char *)drive_, *dir = (char *)dir_, *name = (char *)name_, *ext = (char *)ext_;
  int flags = 0, count = 0;
  if (strchr(path, '*') || strchr(path, '?'))
    flags = 1;
  if (path[1] == ':') {
    *drive++ = path[0];
    *drive++ = ':';
    path += 2;
    flags |= 16;
  }
  *drive = 0;
  const char *last = strchr(path, '\\');
  if (last) {
    for (const char *p = last; p; p = strchr(p + 1, '\\')) {
      count++;
      last = p;
    }
    flags |= 8;
  } else
    last = path;
  if (count == 1)
    *dir++ = *path++;
  else if (last != path)
    while (path <= last)
      *dir++ = *path++;
  *dir = 0;
  const char *dot = strrchr(last, '.');
  if (dot && dot > last) {
    while (path < dot)
      *name++ = *path++;
    flags |= 4;
    if (*path)
      flags |= 2;
    while (*path)
      *ext++ = *path++;
  } else {
    if (*path)
      flags |= 4;
    while (*path)
      *name++ = *path++;
  }
  *name = 0;
  *ext = 0;
  return flags;
}

// qsort: Borland's.  Its order decides the order of the files in an archive
// whenever the comparator ties, so this is that algorithm, step for step:
// median of three into the first slot, partition, keep the larger side on a
// stack, and insertion-sort runs of at most dword_1000CEAC (7) elements.
static inline void qs_swap(uint32_t a, uint32_t b, unsigned width)
{
  uint8_t *x = (uint8_t *)(uintptr_t)a, *y = (uint8_t *)(uintptr_t)b;
  while (width--) {
    uint8_t t = *x;
    *x++ = *y;
    *y++ = t;
  }
}
#define __PE_DECL___sub_10008660
static unsigned int *__sub_10008660(unsigned int base, int n, unsigned int width,
                                    int (__cdecl *cmp)(unsigned int, unsigned int))
{
  uint32_t lo = base, hi = base + n * width, stack[2 * 64];
  uint32_t thresh = *(uint32_t *)0x1000CEAC * width;
  int sp = 0;
  for (;;) {
    while (hi - lo > thresh) {
      uint32_t half = (hi - lo) >> 1, j = hi - width, i = lo + width;
      qs_swap(lo, lo + (half - half % width), width);
      if (cmp(lo + width, j) > 0) qs_swap(j, lo + width, width);
      if (cmp(lo, j) > 0) qs_swap(j, lo, width);
      if (cmp(lo + width, lo) > 0) qs_swap(lo, lo + width, width);
      for (;;) {
        do i += width; while (cmp(i, lo) < 0);
        do j -= width; while (cmp(j, lo) > 0);
        if (i > j)
          break;
        qs_swap(j, i, width);
      }
      qs_swap(j, lo, width);
      if ((int32_t)(j - lo) > (int32_t)(hi - i)) {
        stack[sp++] = lo; stack[sp++] = j; lo = i;
      } else {
        stack[sp++] = i; stack[sp++] = hi; hi = j;
      }
    }
    for (uint32_t i = lo + width; i < hi; i += width)
      for (uint32_t j = i; j > lo && cmp(j - width, j) > 0; j -= width)
        qs_swap(j, j - width, width);
    if (!sp)
      return (unsigned int *)(uintptr_t)base;
    hi = stack[--sp];
    lo = stack[--sp];
  }
}

// Drives and directories: there is one drive, C:, and the directory vbn2
// started in is its root.
#define __PE_DECL___sub_100088EA
