#define __PE_DECL___sub_10008850
static char *__sub_10008850(void *buf, unsigned __int16 size)    // getcwd: "C:\" and the path
{
  char cwd[600];
  snprintf(cwd, sizeof cwd, "C:\\%s", dos_cwd);
  for (char *p = cwd; *p; p++)
    if (*p == '/')
      *p = '\\';
  unsigned len = strlen(cwd) + 1;
  if (!buf) {
    buf = image_malloc(len > size ? len : size);
    if (!buf) { dos_error(8); return NULL; }
  } else if (len > size) {
    dos_error(0x3EB);
    return NULL;
  }
  memcpy(buf, cwd, len);
  return (char *)buf;
}
